			if outputFormatSeen {
				fmt.Fprintf(os.Stderr, "error: the argument '--output-format <OUTPUT_FORMAT>' cannot be used multiple times\n\nUsage: %s [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.\n", prog)
