func loadConfig(configPath string, verbose bool) (*Config, bool, *Diagnostic) {
	// configPath is either "./oranda.json" (default) or custom via --config-path
	// If file doesn't exist or is directory, return defaults, found=false, no error (and verbose prints DEBUG)
	info, err := os.Stat(configPath)
	if err != nil || info.IsDir() {
		if verbose {
