// Helper to compute line/col/offset
func offsetToLineCol(content string, offset int) (line, col int) {
	line, col = 1, 1
	for i := 0; i < offset && i < len(content); i++ {
		if content[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	return line, col
}

func lineColToOffset(content string, line, col int) int {
	curLine, curCol := 1, 1
	for i := 0; i < len(content); i++ {
		if curLine == line && curCol == col {
			return i
		}
		if content[i] == '\n' {
			curLine++
			curCol = 1
		} else {
			curCol++
		}
	}
	return len(content)
}

// Find field name closing quote offset for unknown field error
func findFieldEnd(content string, fieldName string, searchStart int) int {
	// Search for "fieldName" (with quotes) starting from searchStart
	needle := `"` + fieldName + `"`
	idx := strings.Index(content[searchStart:], needle)
	if idx == -1 {
		return -1
	}
	absIdx := searchStart + idx
	// Closing quote is at absIdx + len(needle) -1
	return absIdx + len(needle) - 1
}

