func invalidTypeForStruct(content, filename, fieldName string, value interface{}, structName string, fieldCount int) *Diagnostic {
	// Find value end offset for fieldName
	// Search for "fieldName": then value
	off := findValueEnd(content, fieldName)
	if off == -1 {
		off = 0
	}
	l, c := offsetToLineCol(content, off)
	var msg string
	switch v := value.(type) {
	case []interface{}:
		msg = fmt.Sprintf("invalid length %d, expected struct %s with %d elements at line %d column %d", len(v), structName, fieldCount, l, c)
	case string:
		msg = fmt.Sprintf("invalid type: string \"%s\", expected struct %s at line %d column %d", v, structName, l, c)
	case json.Number:
		numStr := string(v)
		if strings.Contains(numStr, ".") || strings.Contains(numStr, "e") || strings.Contains(numStr, "E") {
			msg = fmt.Sprintf("invalid type: floating point `%s`, expected struct %s at line %d column %d", numStr, structName, l, c)
		} else {
			msg = fmt.Sprintf("invalid type: integer `%s`, expected struct %s at line %d column %d", numStr, structName, l, c)
		}
	case bool:
		bstr := "false"
		if v {
			bstr = "true"
		}
		msg = fmt.Sprintf("invalid type: boolean `%s`, expected struct %s at line %d column %d", bstr, structName, l, c)
	case float64:
		// Should not happen with UseNumber, but just in case
		msg = fmt.Sprintf("invalid type: floating point `%v`, expected struct %s at line %d column %d", v, structName, l, c)
	default:
		// map? Should not happen (we already checked map)
		// null? Handled by caller (v != nil check), so not here.
		msg = fmt.Sprintf("invalid type, expected struct %s at line %d column %d", structName, l, c)
	}
	return &Diagnostic{
		Message: "failed to parse JSON", Severity: "error",
		Causes: []string{msg},
		Filename: &filename, Labels: []Label{{Span: Span{Offset: off, Length: 1}}},
	}
}

func findValueEnd(content, fieldName string) int {
	// Find "fieldName": then skip ws, :, ws, then find value end
	needle := `"` + fieldName + `"`
	idx := strings.Index(content, needle)
	if idx == -1 {
		return -1
	}
	pos := idx + len(needle)
	// Skip ws
	for pos < len(content) && (content[pos] == ' ' || content[pos] == '\t' || content[pos] == '\n' || content[pos] == '\r') {
		pos++
	}
	if pos >= len(content) || content[pos] != ':' {
		return -1
	}
	pos++ // skip :
	for pos < len(content) && (content[pos] == ' ' || content[pos] == '\t' || content[pos] == '\n' || content[pos] == '\r') {
		pos++
	}
	if pos >= len(content) {
		return -1
	}
	c := content[pos]
	if c == '"' {
		// String: find closing quote (handle escapes)
		p := pos + 1
		for p < len(content) {
			if content[p] == '\\' {
				p += 2
				continue
			}
			if content[p] == '"' {
				return p
			}
			p++
		}
		return -1
	} else if c == '[' {
		// Array: find matching ]? For invalid length error, need ] position (end of array). For "[]", pos at [, end at ]. For "[1,2]"? But our case for struct expected, value is array like [] (empty). Find matching ] with nesting? Simplify: find first ] at same depth? For "[]", it's pos+1. For "[{}]", need to handle nested. Implement bracket counting.
		depth := 0
		inStr := false
		esc := false
		for p := pos; p < len(content); p++ {
			ch := content[p]
			if inStr {
				if esc {
					esc = false
				} else if ch == '\\' {
					esc = true
				} else if ch == '"' {
					inStr = false
				}
				continue
			}
			if ch == '"' {
				inStr = true
			} else if ch == '[' {
				depth++
			} else if ch == ']' {
				depth--
				if depth == 0 {
					return p
				}
			}
		}
		return -1
	} else if c == '{' {
		// Object: find matching }? For our case, value is object but we already handled map? This function is for non-object values, so c=='{' shouldn't happen. But just in case, find matching }.
		depth := 0
		inStr := false
		esc := false
		for p := pos; p < len(content); p++ {
			ch := content[p]
			if inStr {
				if esc {
					esc = false
				} else if ch == '\\' {
					esc = true
				} else if ch == '"' {
					inStr = false
				}
				continue
			}
			if ch == '"' {
				inStr = true
			} else if ch == '{' {
				depth++
			} else if ch == '}' {
				depth--
				if depth == 0 {
					return p
				}
			}
		}
		return -1
	} else if c == 't' {
		// true (4 chars)
		if strings.HasPrefix(content[pos:], "true") {
			return pos + 3
		}
		return -1
	} else if c == 'f' {
		if strings.HasPrefix(content[pos:], "false") {
			return pos + 4
		}
		return -1
	} else if c == 'n' {
		if strings.HasPrefix(content[pos:], "null") {
			return pos + 3
		}
		return -1
	} else if c == '-' || (c >= '0' && c <= '9') {
		// Number: consume number chars
		p := pos
		if content[p] == '-' {
			p++
		}
		for p < len(content) && content[p] >= '0' && content[p] <= '9' {
			p++
		}
		if p < len(content) && content[p] == '.' {
			p++
			for p < len(content) && content[p] >= '0' && content[p] <= '9' {
				p++
			}
		}
		if p < len(content) && (content[p] == 'e' || content[p] == 'E') {
			p++
			if p < len(content) && (content[p] == '+' || content[p] == '-') {
				p++
			}
			for p < len(content) && content[p] >= '0' && content[p] <= '9' {
				p++
			}
		}
		return p - 1
	}
	return -1
}

