			msg := fmt.Sprintf("unknown field `%s`, expected one of `name`, `version`, `description`, `homepage`, `repository`, `readme_path`, `license` at line %d column %d", k, l, c)
			return nil, &Diagnostic{Message: "failed to parse JSON", Severity: "error", Causes: []string{msg}, Filename: &filename, Labels: []Label{{Span: Span{Offset: off, Length: 1}}}}
		}
	}
	cfg := &ProjectConfig{}
	// Each field must be string or null
	for _, field := range []string{"name", "version", "description", "homepage", "repository", "readme_path", "license"} {
		if v, ok := m[field]; ok && v != nil {
			s, ok := v.(string)
			if !ok {
				off := findValueEnd(content, field)
				l, c := offsetToLineCol(content, off)
				var typeStr string
				switch vv := v.(type) {
				case json.Number:
					numStr := string(vv)
					if strings.Contains(numStr, ".") || strings.Contains(numStr, "e") || strings.Contains(numStr, "E") {
						typeStr = fmt.Sprintf("floating point `%s`", numStr)
					} else {
						typeStr = fmt.Sprintf("integer `%s`", numStr)
					}
				case bool:
					if vv {
						typeStr = "boolean `true`"
					} else {
						typeStr = "boolean `false`"
					}
				case []interface{}:
					typeStr = "sequence"
				case map[string]interface{}:
					typeStr = "map"
				default:
					typeStr = fmt.Sprintf("%T", v)
				}
				msg := fmt.Sprintf("invalid type: %s, expected a string at line %d column %d", typeStr, l, c)
				return nil, &Diagnostic{Message: "failed to parse JSON", Severity: "error", Causes: []string{msg}, Filename: &filename, Labels: []Label{{Span: Span{Offset: off, Length: 1}}}}
			}
			switch field {
			case "name":
				cfg.Name = &s
			case "version":
				cfg.Version = &s
			case "description":
				cfg.Description = &s
			case "homepage":
				cfg.Homepage = &s
			case "repository":
				cfg.Repository = &s
			case "readme_path":
				cfg.ReadmePath = &s
			case "license":
