			name := arg
			if idx := strings.Index(arg, "="); idx != -1 {
				name = arg[:idx]
			}
			// Candidates for build: --json-only, --project-root, --config-path, --verbose, --output-format, --help
			candidates := []string{"--json-only", "--project-root", "--config-path", "--verbose", "--output-format", "--help"}
			similar := findSimilarArg(name, candidates)
			if similar != "" {
				var usage string
				if similar == "--verbose" {
