				} else if similar == "--output-format" {
					usage = fmt.Sprintf("Usage: %s build --output-format <OUTPUT_FORMAT>", prog)
				} else if similar == "--help" {
					usage = fmt.Sprintf("Usage: %s build --help", prog) // guess? Need to test build --helpful tip? For build --helpful, what Usage? Likely `build --help`? Let's assume.
				} else {
					// Local flag: show all locals with <>| ?
					usage = fmt.Sprintf("Usage: %s build <--project-root <PROJECT_ROOT>|--config-path <CONFIG_PATH>|--json-only>", prog)
				}
				fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: a similar argument exists: '%s'\n\n%s\n\nFor more information, try '--help'.\n", arg, similar, usage)
