			}
			return 2
		}
		// Positional (unexpected)
		fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\nUsage: %s build [OPTIONS]\n\nFor more information, try '--help'.\n", arg, prog)
		return 2
	}
	// Execute build
	_ = projectRoot
	return doBuild(prog, g.verbose, g.outputFormat, jsonOnly, projectRoot, configPath)
}

