func parseGlobalArg(prog, subUsage string, arg string, args []string, idx *int, g *globalOpts) (isGlobal bool, helpAction string, errMsg string) {
	// Returns isGlobal (whether arg is a global), helpAction ("short"/"long"/""), errMsg (if error, full stderr text + exit 2)
	// subUsage is like "build", "serve", etc. for Usage in errors
	// idx points to current arg index, may be incremented if value consumed
	if arg == "-h" {
		return true, "short", ""
	}
	if arg == "--help" {
		return true, "long", ""
	}
	if arg == "-v" || arg == "--verbose" {
		if g.verboseSeen {
			return true, "", fmt.Sprintf("error: the argument '--verbose' cannot be used multiple times\n\nUsage: %s %s\n\nFor more information, try '--help'.\n", prog, subUsageForError(prog, subUsage))
		}
		g.verboseSeen = true
		g.verbose = true
		return true, "", ""
	}
	if arg == "--output-format" {
		if g.outputFormatSeen {
			return true, "", fmt.Sprintf("error: the argument '--output-format <OUTPUT_FORMAT>' cannot be used multiple times\n\nUsage: %s %s\n\nFor more information, try '--help'.\n", prog, subUsageForError(prog, subUsage))
		}
		g.outputFormatSeen = true
		*idx++
		if *idx >= len(args) {
			return true, "", fmt.Sprintf("error: a value is required for '--output-format <OUTPUT_FORMAT>' but none was supplied\n  [possible values: human, json]\n\nFor more information, try '--help'.\n")
		}
		val := args[*idx]
		if val != "human" && val != "json" {
			return true, "", fmt.Sprintf("error: invalid value '%s' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human, json]\n\nFor more information, try '--help'.\n", val)
		}
		g.outputFormat = val
		return true, "", ""
	}
	if strings.HasPrefix(arg, "--output-format=") {
		if g.outputFormatSeen {
			return true, "", fmt.Sprintf("error: the argument '--output-format <OUTPUT_FORMAT>' cannot be used multiple times\n\nUsage: %s %s\n\nFor more information, try '--help'.\n", prog, subUsageForError(prog, subUsage))
		}
		g.outputFormatSeen = true
		val := strings.TrimPrefix(arg, "--output-format=")
		if val != "human" && val != "json" {
			return true, "", fmt.Sprintf("error: invalid value '%s' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human, json]\n\nFor more information, try '--help'.\n", val)
		}
		g.outputFormat = val
		return true, "", ""
	}
	// Combined shorts like -vh? Handle in caller (needs to handle -v + -h together). For now, return false for combined.
	return false, "", ""
}

func subUsageForError(prog, sub string) string {
	// Returns Usage suffix for error messages, e.g., for build: "build [OPTIONS]", for top: "[OPTIONS] <COMMAND>", etc.
	switch sub {
	case "top":
		return "[OPTIONS] <COMMAND>"
	case "build":
		return "build [OPTIONS]"
	case "dev":
		return "dev [OPTIONS]"
	case "serve":
		return "serve [OPTIONS]"
	case "generate":
		return "generate [OPTIONS] <COMMAND>"
	case "ci":
		return "generate ci [OPTIONS]"
	case "gencss":
		return "generate-css [OPTIONS]"
	default:
		return sub
	}
}

