func parsePort(s string) (uint16, error) {
	// Must be digits only? For "abc", error "invalid digit found in string"
	// For "99999", error "99999 is not in 0..=65535"
	// For "-1", error "-1 is not in 0..=65535" (when via =)
	// For "" (empty via --port=)? What error? Need to test. Likely "invalid digit..."? Or "cannot parse integer..."? Let's handle.
	if s == "" {
		return 0, fmt.Errorf("invalid digit found in string")
	}
	// Check for non-digits (except leading -? For "-1", it contains '-', but error is range, not digit. So '-' is allowed for range check? Actually "-1" parses as integer -1, then range check fails. While "abc" fails digit check.
	// So try to parse as int first.
	if strings.HasPrefix(s, "-") || strings.HasPrefix(s, "+") {
		// Parse as int
		n, err := strconv.Atoi(s)
		if err != nil {
			// Contains non-digits after sign? e.g., "-abc"? Then digit error? Let's return digit error.
			return 0, fmt.Errorf("invalid digit found in string")
		}
		if n < 0 || n > 65535 {
			return 0, fmt.Errorf("%s is not in 0..=65535", s)
		}
		return uint16(n), nil
	}
	// Check all digits
	for _, c := range s {
		if c < '0' || c > '9' {
			return 0, fmt.Errorf("invalid digit found in string")
		}
	}
	n, _ := strconv.Atoi(s)
	if n < 0 || n > 65535 {
		return 0, fmt.Errorf("%s is not in 0..=65535", s)
	}
	return uint16(n), nil
}
