package main
import "fmt"
func jaroWinkler(s1, s2 string) float64 {
	if s1 == s2 { return 1.0 }
	len1, len2 := len(s1), len(s2)
	if len1 == 0 || len2 == 0 { return 0.0 }
	matchDist := len1
	if len2 > len1 { matchDist = len2 }
	matchDist = matchDist/2 - 1
	if matchDist < 0 { matchDist = 0 }
	s1Matches := make([]bool, len1)
	s2Matches := make([]bool, len2)
	matches := 0
	for i := 0; i < len1; i++ {
		start := i - matchDist
		if start < 0 { start = 0 }
		end := i + matchDist + 1
		if end > len2 { end = len2 }
		for j := start; j < end; j++ {
			if s2Matches[j] { continue }
			if s1[i] != s2[j] { continue }
			s1Matches[i] = true
			s2Matches[j] = true
			matches++
			break
		}
	}
	if matches == 0 { return 0.0 }
	transpositions := 0
	k := 0
	for i := 0; i < len1; i++ {
		if !s1Matches[i] { continue }
		for !s2Matches[k] { k++ }
		if s1[i] != s2[k] { transpositions++ }
		k++
