func parseCargoRepository(content string) string {
	// Simple TOML parse for [package] repository = "..."
	// Find [package] section, then repository line
	lines := strings.Split(content, "\n")
	inPackage := false
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "[") {
			// Section header? Check if [package] (exact, not [package.metadata...]? For [package], inPackage true. For others, false.
			if trimmed == "[package]" {
				inPackage = true
			} else {
				inPackage = false
			}
			continue
		}
		if inPackage {
			// Look for repository = "..." (with possible quotes, comments?)
			if strings.HasPrefix(trimmed, "repository") {
				// Split on =
				parts := strings.SplitN(trimmed, "=", 2)
				if len(parts) == 2 {
					val := strings.TrimSpace(parts[1])
					// Remove comments? TOML comments start with # (if not in string). For simplicity, split on # and take first? But repository URL contains #? No (fragment? Unlikely). Good.
					if idx := strings.Index(val, "#"); idx != -1 {
						// Check if # inside quotes? For repository = "https://...#...", # inside string, not comment. Our simple split would break. Need to handle quotes.
						// For now, assume no comments on repository line (common).
						val = strings.TrimSpace(val[:idx])
					}
					// Remove quotes (single or double)
					val = strings.Trim(val, `"'`)
					// Handle triple quotes? Unlikely. Good.
					return val
				}
			}
		}
	}
	return ""
}

