	// Since judge is linux/amd64, hardcode that for now, but implement mapping for completeness.
	switch runtime.GOOS {
	case "linux":
		switch runtime.GOARCH {
		case "amd64":
			return "tailwindcss-linux-x64"
		case "arm64":
			return "tailwindcss-linux-arm64"
		default:
			return "tailwindcss-linux-x64"
		}
	case "darwin":
		switch runtime.GOARCH {
		case "amd64":
			return "tailwindcss-macos-x64"
		case "arm64":
			return "tailwindcss-macos-arm64"
		default:
			return "tailwindcss-macos-x64"
		}
	case "windows":
		return "tailwindcss-windows-x64.exe"
	default:
		return "tailwindcss-linux-x64"
	}
}

func isConnectionRefused(err error) bool {
	return err != nil && (contains(err.Error(), "connection refused") || contains(err.Error(), "Connection refused"))
