	// Observed for linux/amd64: tailwindcss-linux-x64
	// Guess for others: linux/arm64 -> linux-arm64? darwin/amd64 -> macos-x64? darwin/arm64 -> macos-arm64? windows/amd64 -> windows-x64.exe?
	// Since judge is linux/amd64, hardcode that for now, but implement mapping for completeness.
	switch runtime.GOOS {
	case "linux":
		switch runtime.GOARCH {
		case "amd64":
			return "tailwindcss-linux-x64"
		case "arm64":
			return "tailwindcss-linux-arm64"
		default:
