func doDevInitialBuild(cfg *Config, distDir string, verbose bool, outputFormat string) int {
	// Perform normal build (like doBuildImpl but with already-loaded cfg, no reload, no DEBUG re-print)
	// For offline, this will fail on CSS fetch (same as build). Print Fetching... to stdout, error to stderr, return 255.
	// Reuse logic from doBuildImpl but without config reload.
	// Determine CSS version
	cssVersion := "v0.6.1"
	if cfg != nil && cfg.Styles != nil && cfg.Styles.OrandaCSSVersion != nil {
		cssVersion = *cfg.Styles.OrandaCSSVersion
	}
	// Create dist dir + favicon (same as build)
	os.MkdirAll(distDir, 0755)
	customFavicon := ""
	if cfg != nil && cfg.Styles != nil && cfg.Styles.Favicon != nil {
		customFavicon = *cfg.Styles.Favicon
	}
	if customFavicon == "" {
		if len(defaultFavicon) > 0 {
			os.WriteFile(filepath.Join(distDir, "favicon.ico"), defaultFavicon, 0644)
		}
	}
	proxyURL := fmt.Sprintf("https://octolotl.axodotdev.host/downloads/axodotdev/oranda/%s/oranda.css", cssVersion)
	fallbackURL := fmt.Sprintf("https://api.github.com/repos/axodotdev/oranda/releases/download/%s/oranda.css", cssVersion)
	_, err1 := httpGet(proxyURL)
	if err1 != nil {
		mappedInner := mappedInnerError(err1)
		fmt.Fprintf(os.Stdout, "Fetching from proxy encountered an error:\n error sending request for url (%s): %s.\n Falling back to GitHub directly...\n", proxyURL, mappedInner)
		_, err2 := httpGet(fallbackURL)
		if err2 != nil {
			inner2 := mappedInnerError(err2)
			var msg string
			var causes []string
			if isDNSError(err2) {
				dnsDetail := "Temporary failure in name resolution"
				msg = fmt.Sprintf("error sending request for url (%s): error trying to connect: dns error: failed to lookup address information: %s", fallbackURL, dnsDetail)
				causes = []string{
					fmt.Sprintf("error trying to connect: dns error: failed to lookup address information: %s", dnsDetail),
					fmt.Sprintf("dns error: failed to lookup address information: %s", dnsDetail),
					fmt.Sprintf("failed to lookup address information: %s", dnsDetail),
				}
				_ = inner2
			} else {
				msg = fmt.Sprintf("error sending request for url (%s): %s", fallbackURL, inner2)
				causes = []string{inner2}
			}
			d := Diagnostic{Message: msg, Severity: "error", Causes: causes, Labels: []Label{}}
			printErrorDiagnostic(d, outputFormat)
			return 255
		}
	}
	fmt.Fprintf(os.Stdout, "✓ >o_o< SUCCESS: Your site build is located in `%s`.\n", distDir)
	return 0
}

func devWatchLoop(watchList []string, cfg *Config, distDir string, verbose bool, outputFormat string, cfgPath string) {
	// Poll watched files for changes (mtime + size? Or just mtime?).
	// Store initial modtimes
	type fileInfo struct {
		mtime time.Time
		size  int64
		exists bool
	}
	infos := make(map[string]fileInfo)
	for _, f := range watchList {
		if info, err := os.Stat(f); err == nil {
			infos[f] = fileInfo{mtime: info.ModTime(), size: info.Size(), exists: true}
		} else {
			infos[f] = fileInfo{exists: false}
		}
	}
	// Poll every 500ms? Original uses notify (instant, not polling). Our polling will have delay (~500ms). For tests with sleep 2-3s after change, 500ms is fine.
	for {
		time.Sleep(500 * time.Millisecond)
		var changed []string
		for _, f := range watchList {
			info, err := os.Stat(f)
			prev := infos[f]
			if err != nil {
				// Deleted? If previously existed, now not -> changed?
				if prev.exists {
					// File deleted: consider changed? Original notify would detect delete. For rebuild, should trigger? Likely yes. Add to changed with abs path?
					abs, _ := filepath.Abs(f)
					changed = append(changed, abs)
					infos[f] = fileInfo{exists: false}
				}
				continue
			}
			if !prev.exists {
				// Created (previously not exist, now exists): changed
				abs, _ := filepath.Abs(f)
				changed = append(changed, abs)
				infos[f] = fileInfo{mtime: info.ModTime(), size: info.Size(), exists: true}
				continue
			}
			// Compare mtime and size? Original notify triggers on write (mtime change). Use mtime + size.
			if !info.ModTime().Equal(prev.mtime) || info.Size() != prev.size {
				abs, _ := filepath.Abs(f)
				changed = append(changed, abs)
				infos[f] = fileInfo{mtime: info.ModTime(), size: info.Size(), exists: true}
			}
		}
		if len(changed) > 0 {
			// Print Path(s) [...] changed, rebuilding...
			// Format: `Path(s) ["<abs1>", "<abs2>"] changed, rebuilding...`? For single, `["/tmp/..."]`. For multiple, comma+space? Need to test multiple. Assume `", "` separator.
			fmt.Fprintf(os.Stdout, "↪ >o_o< INFO: Path(s) [")
			for i, p := range changed {
				if i > 0 {
					fmt.Fprintf(os.Stdout, ", ")
				}
				fmt.Fprintf(os.Stdout, "\"%s\"", p)
			}
			fmt.Fprintf(os.Stdout, "] changed, rebuilding...\n")
			// Rebuild (normal build, non-fatal on failure: print error but continue)
			// Need to reload config? Since oranda.json may have changed, reload. For README change, config same. For simplicity, reload config each rebuild (like original does?).
			// Reload config (with verbose? Does rebuild print DEBUG? For rebuild with verbose, does it print DEBUG? Likely not (only initial). For rebuild, even with verbose, no DEBUG? Need to test dev verbose rebuild. For now, reload without verbose DEBUG (pass verbose=false for reload to avoid duplicate DEBUG? Actually initial already printed DEBUG, rebuild should not print DEBUG again. Good. Pass verbose=false for reload.
			newCfg, _, diag := loadConfig(cfgPath, false)
			if diag != nil {
				printErrorDiagnostic(*diag, outputFormat)
				// Continue watching (don't exit)
				continue
			}
			// Update distDir in case config changed dist_dir? Original rebuild would use new distDir? Possibly. For simplicity, use new distDir for rebuild, but server still serves old distDir? Hmm. Original dev server serves from distDir determined at startup; if config changes dist_dir, does server switch? Unlikely (server keeps old). But rebuild writes to new distDir? Then server serves old (stale)? Complex. For now, use original distDir for rebuild (ignore config change for distDir)? Or use new? Let's use new distDir for rebuild (like build does).
			newDist := distDir
			if newCfg != nil && newCfg.Build != nil && newCfg.Build.DistDir != nil {
				newDist = *newCfg.Build.DistDir
			}
			// Perform build (normal, non-fatal)
			ret := doDevRebuild(newCfg, newDist, outputFormat)
			_ = ret
			// Continue (don't exit on failure)
			// Update cfg for next iteration? Since config may have changed (e.g., new watch files? If config adds mdbook, watch list should update? Original dev watch list is fixed at startup (doesn't update on config change)? Or does it re-evaluate? Likely fixed (watch list determined once at startup, not updated). For simplicity, keep original watchList (don't update).
			_ = newCfg
		}
	}
}

