	// Store initial modtimes
	type fileInfo struct {
		mtime time.Time
		size  int64
		exists bool
	}
	infos := make(map[string]fileInfo)
	for _, f := range watchList {
		if info, err := os.Stat(f); err == nil {
			infos[f] = fileInfo{mtime: info.ModTime(), size: info.Size(), exists: true}
		} else {
			infos[f] = fileInfo{exists: false}
		}
	}
	// Poll every 500ms? Original uses notify (instant, not polling). Our polling will have delay (~500ms). For tests with sleep 2-3s after change, 500ms is fine.
	for {
		time.Sleep(500 * time.Millisecond)
		var changed []string
		for _, f := range watchList {
			info, err := os.Stat(f)
			prev := infos[f]
			if err != nil {
				// Deleted? If previously existed, now not -> changed?
				if prev.exists {
					// File deleted: consider changed? Original notify would detect delete. For rebuild, should trigger? Likely yes. Add to changed with abs path?
					abs, _ := filepath.Abs(f)
					changed = append(changed, abs)
					infos[f] = fileInfo{exists: false}
				}
				continue
			}
			if !prev.exists {
				// Created (previously not exist, now exists): changed
				abs, _ := filepath.Abs(f)
				changed = append(changed, abs)
				infos[f] = fileInfo{mtime: info.ModTime(), size: info.Size(), exists: true}
				continue
			}
			// Compare mtime and size? Original notify triggers on write (mtime change). Use mtime + size.
			if !info.ModTime().Equal(prev.mtime) || info.Size() != prev.size {
				abs, _ := filepath.Abs(f)
				changed = append(changed, abs)
				infos[f] = fileInfo{mtime: info.ModTime(), size: info.Size(), exists: true}
			}
		}
		if len(changed) > 0 {
			// Print Path(s) [...] changed, rebuilding...
