func doDevRebuild(cfg *Config, distDir string, outputFormat string) int {
	// Same as initial build but non-fatal (return 0 even on failure? Actually print error but return 0 to continue? The rebuild failure should print error to stderr (+ JSON to stdout if json) but not exit. Good. Return 0 always? Or return 255 but caller ignores? Let's return 0 to indicate continue (but print error).
	cssVersion := "v0.6.1"
	if cfg != nil && cfg.Styles != nil && cfg.Styles.OrandaCSSVersion != nil {
		cssVersion = *cfg.Styles.OrandaCSSVersion
	}
	os.MkdirAll(distDir, 0755)
	customFavicon := ""
	if cfg != nil && cfg.Styles != nil && cfg.Styles.Favicon != nil {
		customFavicon = *cfg.Styles.Favicon
	}
	if customFavicon == "" {
		if len(defaultFavicon) > 0 {
			os.WriteFile(filepath.Join(distDir, "favicon.ico"), defaultFavicon, 0644)
		}
	}
	proxyURL := fmt.Sprintf("https://octolotl.axodotdev.host/downloads/axodotdev/oranda/%s/oranda.css", cssVersion)
	fallbackURL := fmt.Sprintf("https://api.github.com/repos/axodotdev/oranda/releases/download/%s/oranda.css", cssVersion)
	_, err1 := httpGet(proxyURL)
	if err1 != nil {
		mappedInner := mappedInnerError(err1)
		fmt.Fprintf(os.Stdout, "Fetching from proxy encountered an error:\n error sending request for url (%s): %s.\n Falling back to GitHub directly...\n", proxyURL, mappedInner)
		_, err2 := httpGet(fallbackURL)
		if err2 != nil {
			inner2 := mappedInnerError(err2)
			var msg string
			var causes []string
			if isDNSError(err2) {
				dnsDetail := "Temporary failure in name resolution"
				msg = fmt.Sprintf("error sending request for url (%s): error trying to connect: dns error: failed to lookup address information: %s", fallbackURL, dnsDetail)
				causes = []string{
					fmt.Sprintf("error trying to connect: dns error: failed to lookup address information: %s", dnsDetail),
					fmt.Sprintf("dns error: failed to lookup address information: %s", dnsDetail),
					fmt.Sprintf("failed to lookup address information: %s", dnsDetail),
				}
				_ = inner2
			} else {
				msg = fmt.Sprintf("error sending request for url (%s): %s", fallbackURL, inner2)
				causes = []string{inner2}
			}
			d := Diagnostic{Message: msg, Severity: "error", Causes: causes, Labels: []Label{}}
			printErrorDiagnostic(d, outputFormat)
			return 255 // Caller will ignore (continue)
		}
	}
	fmt.Fprintf(os.Stdout, "✓ >o_o< SUCCESS: Your site build is located in `%s`.\n", distDir)
	return 0
}
