func trimSpaceLowerImpl(s string) string {
	// Trim spaces and lowercase without strings package? Use manual.
	// Trim leading/trailing spaces, \t, \r, \n
	start := 0
	for start < len(s) && (s[start] == ' ' || s[start] == '\t' || s[start] == '\r' || s[start] == '\n') {
		start++
	}
	end := len(s)
	for end > start && (s[end-1] == ' ' || s[end-1] == '\t' || s[end-1] == '\r' || s[end-1] == '\n') {
		end--
	}
	trimmed := s[start:end]
	// Lowercase (ASCII only? For y/n, only ASCII. Good.)
	var out []byte
	for i := 0; i < len(trimmed); i++ {
		c := trimmed[i]
		if c >= 'A' && c <= 'Z' {
			c = c - 'A' + 'a'
		}
		out = append(out, c)
	}
	return string(out)
}

